function monthlyCostPerRequest(fixedCost, variableCostPerRequest, requests) {
  if (requests <= 0) {
    throw new RangeError("requests must be positive");
  }
  return (fixedCost + variableCostPerRequest * requests) / requests;
}

function uncachedRequestCount(totalRequests, cacheHitRatio) {
  if (cacheHitRatio < 0 || cacheHitRatio > 1) {
    throw new RangeError("cacheHitRatio must be between 0 and 1");
  }
  return Math.round(totalRequests * (1 - cacheHitRatio));
}

function breakEvenUtilization(onDemandRatePerHour, reservedRatePerHour) {
  if (onDemandRatePerHour <= 0) {
    throw new RangeError("onDemandRatePerHour must be positive");
  }
  return reservedRatePerHour / onDemandRatePerHour;
}

function cheaperOption(onDemandRatePerHour, reservedRatePerHour, expectedUtilization) {
  if (expectedUtilization < 0 || expectedUtilization > 1) {
    throw new RangeError("expectedUtilization must be between 0 and 1");
  }
  const breakEven = reservedRatePerHour / onDemandRatePerHour;
  return expectedUtilization >= breakEven ? "reserved" : "on-demand";
}
